package com.byawasaya.platform.business;
import java.math.BigDecimal; import java.util.UUID;
import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException;
import com.byawasaya.platform.catalog.ProductService; import com.byawasaya.platform.payments.PaymentProviderCredentialsService; import org.springframework.jdbc.core.JdbcTemplate;
@Service @Transactional
public class StoreService {
 private final BusinessRepository businesses; private final ProductService products; private final TenantTableNameResolver tables; private final JdbcTemplate jdbc; private final PaymentProviderCredentialsService paymentCredentials;
 public StoreService(BusinessRepository businesses,ProductService products,TenantTableNameResolver tables,JdbcTemplate jdbc,PaymentProviderCredentialsService paymentCredentials){this.businesses=businesses;this.products=products;this.tables=tables;this.jdbc=jdbc;this.paymentCredentials=paymentCredentials;}
 @Transactional(readOnly=true) public StoreDtos.StoreResponse profile(UUID id){return StoreDtos.StoreResponse.from(find(id));}
 public StoreDtos.StoreResponse update(UUID id,StoreDtos.UpdateSettingsRequest r){if(!"classic".equalsIgnoreCase(r.templateKey()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"The selected storefront template is not available.");if(r.onlinePaymentEnabled()&&!paymentCredentials.anyEnabled(id))throw new ResponseStatusException(HttpStatus.CONFLICT,"Connect and enable at least one verified merchant payment provider first.");if(!r.codEnabled()&&!r.onlinePaymentEnabled())throw new ResponseStatusException(HttpStatus.CONFLICT,"Enable cash on delivery or a connected online payment provider before accepting orders.");var b=find(id);b.setName(r.name().trim());b.setPhone(r.phone()==null?null:r.phone().trim());b.setDescription(r.description());b.setTemplateKey(r.templateKey());b.setPrimaryColor(r.primaryColor());b.setCodEnabled(r.codEnabled());b.setOnlinePaymentEnabled(r.onlinePaymentEnabled());b.setAdvancePaymentPercent(r.advancePaymentPercent());b.setDeliveryFee(r.deliveryFee()==null?BigDecimal.ZERO:r.deliveryFee());b.setMinimumOrderAmount(r.minimumOrderAmount()==null?BigDecimal.ZERO:r.minimumOrderAmount());tables.prefix(id).ifPresent(p->jdbc.update("UPDATE "+tables.table(p,"store_settings")+" SET display_name=?,description=?,template_key=?,primary_color=?,cod_enabled=?,online_payment_enabled=?,advance_payment_percent=?,delivery_fee=?,minimum_order_amount=? WHERE id=1",b.getName(),b.getDescription(),b.getTemplateKey(),b.getPrimaryColor(),b.isCodEnabled(),b.isOnlinePaymentEnabled(),b.getAdvancePaymentPercent(),b.getDeliveryFee(),b.getMinimumOrderAmount()));return StoreDtos.StoreResponse.from(b);}
 @Transactional(readOnly=true) public StoreDtos.PublicStoreResponse publicStore(String slug){var b=businesses.findBySlugIgnoreCase(slug).filter(Business::isOperational).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Store not found."));var providers=b.isOnlinePaymentEnabled()?paymentCredentials.enabledProviders(b.getId()).stream().map(Enum::name).toList():java.util.List.<String>of();return StoreDtos.PublicStoreResponse.from(b,products.list(b.getId(),true),providers);}
 private Business find(UUID id){return businesses.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Store not found."));}
}
